if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_installed_collection() {
    _argc_util_cache 10 _helper_installed_collection "ansible-galaxy_collection:${argc_collections_path[*]:-}"
}

_choice_installed_role() {
    _argc_util_cache 10 _helper_installed_role "ansible-galaxy_role:${argc_roles_path[*]:-}"
}

_helper_installed_collection() {
    command -v jq >/dev/null || return 0
    local args=() path
    for path in "${argc_collections_path[@]:-}"; do
        [[ -n "$path" ]] && args+=(-p "$path")
    done
    ansible-galaxy collection list "${args[@]}" --format json 2>/dev/null |
        jq -r '.[] | keys[]' 2>/dev/null | sort -u
}

_helper_installed_role() {
    local args=() path
    for path in "${argc_roles_path[@]:-}"; do
        [[ -n "$path" ]] && args+=(-p "$path")
    done
    ansible-galaxy role list "${args[@]}" 2>/dev/null |
        sed -n 's/^- \([^, ]*\),.*$/\1/p'
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
